describe('404 Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display 404 page for invalid URL', () => {
    cy.visit('/this-page-does-not-exist');
    cy.get('[data-testid="page-title"]').should('contain', '404');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page Not Found');
    cy.get('[data-testid="back-to-home-button"]').should('be.visible');
    cy.get('[data-testid="back-to-home-button"]').click();
    cy.url().should('eq', Cypress.config().baseUrl);
  });

  it('should handle multiple invalid URL attempts and redirect to home', () => {
    cy.visit('/non-existent-page');
    cy.get('[data-testid="page-title"]').should('contain', '404');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="back-to-home-button"]').click();
    cy.url().should('eq', Cypress.config().baseUrl);
    cy.visit('/another-invalid-path');
    cy.get('[data-testid="page-title"]').should('contain', '440');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="back-to-home-button"]').click();
    cy.url().should('eq', Cypress.config().baseUrl);
  });
});
